29: // makeReferenceImg.cpp
30: // ====================
31: // A program that uses libtiff to create reference PBM/PGM/PPM images from
32: // TIFF files for the unit tests.
33: //
34: // This program was created because the reference images created with
35: // ImageMagick for 32-bit images were not matching the expected pixel values
36: // as extracted from the TIFF files. The command used with ImageMagick was:
37: //
38: // - magick flower-minisblack-32.tif -compress none PGM:flower-minisblack-32.pgm
39: // - magick flower-rgb-contig-32.tif -compress none PPM:flower-rgb-contig-32.ppm
40: // - magick flower-rgb-planar-32.tif -compress none PPM:flower-rgb-planar-32.ppm
41: //
42: // This program uses libtiff to read the TIFF files instead.
43: // ---------------------------------------------------------------------------
44: 
45: #include <string>
46: #include <memory>
47: #include <filesystem>
48: #include <iostream>
49: 
50: #include <tiffio.h>
51: 
52: #include "netpbm.hpp"
53: 
54: void makeReferenceImg(const std::vector<std::string>& testFiles);
55: 
56: int main(int argc, char* argv[]) {
57: 
58:   { // Gray
59:     { // 32 bits
60:       std::vector<std::string> testFiles = {
61:         "libtiff-pics/depth/flower-minisblack-32.tif",
62:         "reference_images/flower-minisblack-32.pgm",
63:       };
64:       makeReferenceImg(testFiles);
65:     }
66:   }
67: 
68:   { // RGB
69:     { // 32 bits
70:       std::vector<std::string> testFiles = {
71:         "libtiff-pics/depth/flower-rgb-contig-32.tif",
72:         "reference_images/flower-rgb-contig-32.ppm",
73:       };
74:       makeReferenceImg(testFiles);
75:     }
76:   }
77: 
78:   { // RGB Planar
79:     { // 32 bits
80:       std::vector<std::string> testFiles = {
81:         "libtiff-pics/depth/flower-rgb-planar-32.tif",
82:         "reference_images/flower-rgb-planar-32.ppm",
83:       };
84:       makeReferenceImg(testFiles);
85:     }
86:   }
87: 
88:   return 0;
89: }
90: 
91: std::filesystem::path getFilePath(std::filesystem::path relativePath) {
92:   std::filesystem::path test_file_path(__FILE__);
93:   std::filesystem::path test_dir = test_file_path.parent_path();
94:   return test_dir / relativePath;
95: }
