97: class TiffImage {
98: public:
99:   TIFF* tiff = nullptr;
100:   uint32_t width = 0;
101:   uint32_t height = 0;
102: 
103:   TiffImage(const std::string& tiffFilePath) {
104:     tiff = TIFFOpen(tiffFilePath.c_str(), "r");
105:     if (!tiff) {
106:       std::cerr << "Failed to open TIFF file: " << tiffFilePath << std::endl;
107:       throw std::runtime_error("Failed to open TIFF file");
108:     }
109:     TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &width);
110:     TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &height);
111:   }
112: 
113:   template <typename T>
114:   void saveAs(const std::string& refFilePath) {
115:     netpbm::Image<T> img;
116:     img.width = width;
117:     img.height = height;
118:     img.pixels.resize(width * height);
119: 
120:     uint16_t samplesPerPixel = 0;
121:     TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
122:     uint16_t bitsPerSample = 0;
123:     TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
124: 
125:     if constexpr (netpbm::is_rgb_v<T>) {
126:       img.maxval = std::numeric_limits<typename T::value_type>::max();
127:       if (samplesPerPixel != 3) {
128:         std::cerr << "Expected 3 samples per pixel for RGB image, got "
129:                   << samplesPerPixel << std::endl;
130:         throw std::runtime_error("Unsupported samples per pixel");
131:       }
132:     } else {
133:       img.maxval = std::numeric_limits<T>::max();
134:       if (samplesPerPixel != 1) {
135:         std::cerr << "Expected 1 sample per pixel for grayscale image, got "
136:                   << samplesPerPixel << std::endl;
137:         throw std::runtime_error("Unsupported samples per pixel");
138:       }
139:     }
140: 
141:     uint16_t planarConfig = 0;
142:     TIFFGetField(tiff, TIFFTAG_PLANARCONFIG, &planarConfig);
143:     if (planarConfig != PLANARCONFIG_CONTIG && planarConfig != PLANARCONFIG_SEPARATE) {
144:       std::cerr << "Only contiguous and separate planar configurations are supported." << std::endl;
145:       throw std::runtime_error("Unsupported planar configuration");
146:     }
147: 
148:     uint32_t numOfStrips = TIFFNumberOfStrips(tiff);
149:     tmsize_t stripSize = TIFFStripSize(tiff);
150:     std::unique_ptr<void, decltype(&_TIFFfree)> stripBuf(_TIFFmalloc(stripSize), _TIFFfree);
151:     if (!stripBuf) {
152:       std::cerr << "Failed to allocate memory for strip buffer." << std::endl;
153:       throw std::runtime_error("Memory allocation failed");
154:     }
155: 
156:     uint32_t rowsPerStrip = 0;
157:     TIFFGetField(tiff, TIFFTAG_ROWSPERSTRIP, &rowsPerStrip);
158: 
159:     if (planarConfig == PLANARCONFIG_CONTIG) {
160:       for (uint32_t stripIndex = 0; stripIndex < numOfStrips; ++stripIndex) {
161:         if (TIFFReadEncodedStrip(tiff, stripIndex, stripBuf.get(), stripSize) < 0) {
162:           std::cerr << "Failed to read strip " << stripIndex << std::endl;
163:           continue;
164:         }
165: 
166:         uint32_t stripRow = stripIndex * rowsPerStrip;
167:         uint32_t rowsInThisStrip = std::min(rowsPerStrip, height - stripRow);
168:         for (uint32_t row = 0; row < rowsInThisStrip; ++row) {
169:           T* srcRow = static_cast<T*>(stripBuf.get()) + row * width; // Assuming contiguous pixels
170:           for (uint32_t col = 0; col < width; ++col) {
171:             uint32_t pixelIndex = (stripRow + row) * width + col;
172:             img.pixels[pixelIndex] = srcRow[col];
173:           }
174:         }
175:       }
176:     } else if (planarConfig == PLANARCONFIG_SEPARATE) {
177:       // Handle separate planar configuration
178:       // Assuming 3 samples per pixel for RGB
179:       if constexpr (!netpbm::is_rgb_v<T>) {
180:         std::cerr << "Separate planar configuration is only supported for RGB images." << std::endl;
181:         throw std::runtime_error("Unsupported planar configuration for grayscale");
182:       }
183:       else {
184:         if (numOfStrips % 3 != 0) {
185:           std::cerr << "Number of strips is not a multiple of 3 for RGB separate planar." << std::endl;
186:           throw std::runtime_error("Invalid number of strips for RGB separate planar");
187:         }
188:         uint32_t stripsPerPlane = numOfStrips / 3;
189:         for (uint32_t planeIndex = 0; planeIndex < 3; ++planeIndex) {
190:           for (uint32_t planeStripIndex = 0; planeStripIndex < stripsPerPlane; ++planeStripIndex) {
191:             uint32_t stripIndex = planeIndex * stripsPerPlane + planeStripIndex;
192:             if (TIFFReadEncodedStrip(tiff, stripIndex, stripBuf.get(), stripSize) < 0) {
193:               std::cerr << "Failed to read strip " << stripIndex << std::endl;
194:               continue;
195:             }
196: 
197:             uint32_t stripRow = planeStripIndex * rowsPerStrip;
198:             uint32_t rowsInThisStrip = std::min(rowsPerStrip, height - stripRow);
199:             for (uint32_t row = 0; row < rowsInThisStrip; ++row) {
200:               auto srcRow = static_cast<typename T::value_type*>(stripBuf.get()) + row * width; // Assuming contiguous pixels
201:               for (uint32_t col = 0; col < width; ++col) {
202:                 uint32_t pixelIndex = (stripRow + row) * width + col;
203:                 img.pixels[pixelIndex][planeIndex] = srcRow[col];
204:               }
205:             }
206:           }
207:         }
208:       }
209:     }
210: 
211:     netpbm::write(refFilePath, img);
212:     std::cout << "Wrote reference image: " << refFilePath << std::endl;
213:   }
214: 
215:   ~TiffImage() {
216:     if (tiff) {
217:       TIFFClose(tiff);
218:       tiff = nullptr;
219:     }
220:   }
221: };
222: 
223: void makeReferenceImg(const std::vector<std::string>& testFiles)
224: {
225:   if (testFiles.size() % 2 != 0) {
226:     throw std::runtime_error("Test files must be in pairs.");
227:   }
228:   for (size_t i = 0; i < testFiles.size() / 2; ++i) {
229:     const auto tiffFilePath = getFilePath(testFiles[2*i + 0]);
230:     const auto refFilePath = getFilePath(testFiles[2*i + 1]);
231:     std::cout << "Test file: " + tiffFilePath.string() << std::endl;
232:     std::cout << "Reference file: " + refFilePath.string() << std::endl;
233: 
234:     TiffImage tiffImage(tiffFilePath.string());
235:     if (tiffImage.width == 0 || tiffImage.height == 0) {
236:       std::cerr << "Invalid image dimensions." << std::endl;
237:       continue;
238:     }
239:     if (refFilePath.extension() == ".pgm") {
240:       tiffImage.saveAs<uint32_t>(refFilePath.string());
241:     } else if (refFilePath.extension() == ".ppm") {
242:       tiffImage.saveAs<netpbm::RGB32>(refFilePath.string());
243:     } else {
244:       std::cerr << "Unsupported reference file format: " << refFilePath << std::endl;
245:       continue;
246:     }
247:   }
248: }

